  const openEditLeaveModal = (permission: any) => {
    const student = (typeof permission.studentId === "object" ? permission.studentId : null) || permission.students || permission.student || null;
    const formatForInput = (dVal: any) => {
      if (!dVal) return "";
      const d = new Date(dVal);
      if (isNaN(d.getTime())) return "";
      const tzOffset = d.getTimezoneOffset() * 60000;
      return new Date(d.getTime() - tzOffset).toISOString().slice(0, 16);
    };

    const sId = student?._id || student?.id || (typeof permission.studentId === 'string' ? permission.studentId : null);
    const sName = student?.name || permission.name || permission.studentName || "Student";
    const sReg = student?.registrationId || permission.registrationId || "";

    setEditLeaveModalData({
      permissionId: permission._id || permission.id,
      studentId: sId,
      studentName: sName,
      registrationId: sReg,
      fromDateTime: formatForInput(permission.fromDateTime),
      toDateTime: formatForInput(permission.toDateTime),
      reason: permission.reason || "",
    });
  };

  const openEditLeaveModalForStudent = (student: any, existingPermission?: any) => {
    const formatForInput = (dVal: any) => {
      if (!dVal) return "";
      const d = new Date(dVal);
      if (isNaN(d.getTime())) return "";
      const tzOffset = d.getTimezoneOffset() * 60000;
      return new Date(d.getTime() - tzOffset).toISOString().slice(0, 16);
    };

    const now = new Date();
    const tzOffset = now.getTimezoneOffset() * 60000;
    const defaultFrom = new Date(now.getTime() - tzOffset).toISOString().slice(0, 16);
    const defaultTo = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000 - tzOffset).toISOString().slice(0, 16);

    setEditLeaveModalData({
      permissionId: existingPermission?._id || existingPermission?.id,
      studentId: (student._id || student.id)?.toString(),
      studentName: student.name || "Student",
      registrationId: student.registrationId || "",
      fromDateTime: formatForInput(existingPermission?.fromDateTime || student.leaveFrom) || defaultFrom,
      toDateTime: formatForInput(existingPermission?.toDateTime || student.leaveTo) || defaultTo,
      reason: existingPermission?.reason || student.leaveReason || "Home Leave",
    });
  };

  const handleSaveEditedLeave = async () => {
    if (!editLeaveModalData) return;
    if (!editLeaveModalData.fromDateTime || !editLeaveModalData.toDateTime) {
      showToast("Please provide both departure and return dates", "error");
      return;
    }
    if (new Date(editLeaveModalData.toDateTime) <= new Date(editLeaveModalData.fromDateTime)) {
      showToast("Return date must be after departure date", "error");
      return;
    }

    setIsSubmittingEditLeave(true);
    try {
      const effectiveUserType = (typeof window !== "undefined" ? localStorage.getItem("userType") : null) || userType || "warden";
      if (editLeaveModalData.permissionId) {
        const res = await fetch("/api/permissions", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            permissionId: editLeaveModalData.permissionId,
            fromDateTime: editLeaveModalData.fromDateTime,
            toDateTime: editLeaveModalData.toDateTime,
            reason: editLeaveModalData.reason,
            userType: effectiveUserType,
          }),
        });
        const data = await res.json();
        if (!res.ok || !data.success) {
          showToast(data.error || "Failed to update leave dates", "error");
          setIsSubmittingEditLeave(false);
          return;
        }
      } else if (editLeaveModalData.studentId) {
        try {
          await fetch("/api/getpass/manual-toggle", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              studentId: editLeaveModalData.studentId,
              action: "out",
              requestType: "HOME-LEAVE",
              reason: editLeaveModalData.reason,
              fromDateTime: editLeaveModalData.fromDateTime,
              toDateTime: editLeaveModalData.toDateTime,
              userType: effectiveUserType,
              operator: effectiveUserType === "dean" || effectiveUserType === "admin" ? "Admin" : "Warden",
            }),
          });
        } catch (e) {
          console.error("Failed to sync manual toggle:", e);
        }
      }

      setPermissions((prev) =>
        prev.map((p) => {
          const pId = p._id || p.id;
          if (pId === editLeaveModalData.permissionId) {
            return {
              ...p,
              fromDateTime: editLeaveModalData.fromDateTime,
              toDateTime: editLeaveModalData.toDateTime,
              reason: editLeaveModalData.reason,
            };
          }
          return p;
        })
      );

      if (editLeaveModalData.studentId) {
        setSelectedRoomStudents((prev) =>
          prev.map((s) => {
            const sId = (s.id || s._id)?.toString();
            if (sId === editLeaveModalData.studentId) {
              return {
                ...s,
                leaveFrom: editLeaveModalData.fromDateTime,
                leaveTo: editLeaveModalData.toDateTime,
                leaveReason: editLeaveModalData.reason,
              };
            }
            return s;
          })
        );

        setStudents((prev) =>
          prev.map((s) => {
            const sId = (s.id || s._id)?.toString();
            if (sId === editLeaveModalData.studentId) {
              return {
                ...s,
                leaveFrom: editLeaveModalData.fromDateTime,
                leaveTo: editLeaveModalData.toDateTime,
                leaveReason: editLeaveModalData.reason,
              };
            }
            return s;
          })
        );
      }

      showToast("Leave details and return date updated successfully!", "success");
      setEditLeaveModalData(null);
    } catch (err: any) {
      console.error("Save edited leave error:", err);
      showToast("Error: " + (err.message || "Failed to update leave"), "error");
    } finally {
      setIsSubmittingEditLeave(false);
    }
  };

  const handleBulkDeletePermissions = async () => {
    if (selectedPermissionIds.length === 0) return;
    if (!await showConfirm(`Are you sure you want to permanently delete ${selectedPermissionIds.length} selected permission record(s)? This action cannot be undone.`)) return;

    try {
      setIsDeletingPermissions(true);
      const res = await fetch("/api/permissions", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ permissionIds: selectedPermissionIds }),
      });
      const data = await res.json();
      if (data.success) {
        showToast(`Successfully deleted ${selectedPermissionIds.length} permission record(s).`, "success");
        setSelectedPermissionIds([]);
        fetchPermissions(filter, true);
      } else {
        showToast(data.error || "Failed to delete permissions.", "error");
      }
    } catch (err: any) {
      console.error(err);
      showToast(err.message || "Failed to delete permissions.", "error");
    } finally {
      setIsDeletingPermissions(false);
    }
  };

  const handleBulkHidePermissions = async (shouldHide: boolean = true) => {
    if (selectedPermissionIds.length === 0) return;
    const actionText = shouldHide ? "hide" : "unhide";
    if (!await showConfirm(`Are you sure you want to ${actionText} ${selectedPermissionIds.length} selected permission record(s)?`)) return;

    try {
      setIsHidingPermissions(true);
      const res = await fetch("/api/permissions", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          permissionIds: selectedPermissionIds,
          action: shouldHide ? "bulkHide" : "bulkUnhide",
          isHidden: shouldHide
        }),
      });
      const data = await res.json();
      if (data.success) {
        showToast(`Successfully ${shouldHide ? 'hidden' : 'unhidden'} ${selectedPermissionIds.length} permission record(s).`, "success");
        setSelectedPermissionIds([]);
        fetchPermissions(filter, true);
      } else {
        showToast(data.error || `Failed to ${actionText} permissions.`, "error");
      }
    } catch (err: any) {
      console.error(err);
      showToast(err.message || `Failed to ${actionText} permissions.`, "error");
    } finally {
      setIsHidingPermissions(false);
    }
  };

  const startWardenCamera = async () => {
    try {
      setIsWardenCameraOpen(true);
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
      setTimeout(() => {
        if (wardenVideoRef.current) {
          wardenVideoRef.current.srcObject = stream;
        }
      }, 100);
    } catch (err) {
      showToast("Could not access camera: " + err, "error");
      setIsWardenCameraOpen(false);
    }
  };

  const stopWardenCamera = () => {
    if (wardenVideoRef.current && wardenVideoRef.current.srcObject) {
      const stream = wardenVideoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      wardenVideoRef.current.srcObject = null;
    }
    setIsWardenCameraOpen(false);
  };

  const captureWardenPhoto = (fieldId: string) => {
    if (wardenVideoRef.current) {
      const canvas = document.createElement("canvas");
      canvas.width = wardenVideoRef.current.videoWidth || 640;
      canvas.height = wardenVideoRef.current.videoHeight || 480;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(wardenVideoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg");
        setAddStudentForm(prev => ({ ...prev, [fieldId]: dataUrl }));
        stopWardenCamera();
      }
    }
  };

  const checkFieldUniqueness = async (fieldId: string, value: string) => {
    const val = value.trim();
    if (!val) {
      setDuplicateWarnings(prev => {
        const updated = { ...prev };
        delete updated[fieldId];
        return updated;
      });
      return;
    }

    let checkField = "";
    if (fieldId === "phoneNumber") checkField = "phoneNumber";
    if (fieldId === "email") checkField = "email";
    if (fieldId === "erpInformation") checkField = "erpInformation";

    if (!checkField) return;

    // Length pre-validations
    if (fieldId === "phoneNumber") {
      if (val.length < 10) {
        setDuplicateWarnings(prev => ({
          ...prev,
          [fieldId]: "⚠️ Must be exactly 10 digits"
        }));
        return;
      }
      if (!/^[6-9]/.test(val)) {
        setDuplicateWarnings(prev => ({
          ...prev,
          [fieldId]: "⚠️ Must start with 6, 7, 8, or 9"
        }));
        return;
      }
    }
    if (fieldId === "email" && !val.includes("@")) return;
    if (fieldId === "erpInformation" && val.length < 3) return;

    try {
      const res = await fetch(`/api/students?checkValue=${encodeURIComponent(val)}&checkField=${checkField}`);
      const data = await res.json();
      if (res.ok && data.exists) {
        setDuplicateWarnings(prev => ({
          ...prev,
          [fieldId]: `⚠️ Already registered to student "${data.studentName || 'unnamed'}"`
        }));
      } else {
        setDuplicateWarnings(prev => {
          const updated = { ...prev };
          delete updated[fieldId];
          return updated;
        });
      }
    } catch (err) {
      console.warn("Failed to check duplicate:", err);
    }
  };

  const handleSaveManualStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSavingStudent) return;

    // Prevent saving if there are active duplicate warnings
    const hasWarnings = Object.keys(duplicateWarnings).length > 0;
    if (hasWarnings) {
      showToast("Cannot save student profile: Please resolve duplicate values first!", "error");
      return;
    }

    const email = addStudentForm.email?.trim() || "";
    const phoneNumber = addStudentForm.phoneNumber?.trim() || "";
    const hostelName = isWarden 
      ? (authorizedHostels.length > 1 ? (addStudentForm.hostelName || "") : (authorizedHostels[0] || ""))
      : (addStudentForm.hostelName || "");
    const roomNumber = addStudentForm.roomNumber?.trim() || "";
    const floorNumber = addStudentForm.floorNumber || "GND FLOOR";

    if (!email) {
      showToast("Email address is required for credentials linking!", "error");
      return;
    }
    if (!phoneNumber) {
      showToast("Phone number is required!", "error");
      return;
    }
    if (!hostelName) {
      showToast("Hostel name is required!", "error");
      return;
    }
    if (!roomNumber) {
      showToast("Room number is required!", "error");
      return;
    }

    try {
      setIsSavingStudent(true);
      const dummyUid = `temp_admin_added_${email.toLowerCase().replace(/[^a-z0-9]/g, "_")}`;
      
      const payload = {
        ...addStudentForm,
        firebaseUID: dummyUid,
        hostelName,
        roomNumber,
        floorNumber,
        email,
        phoneNumber
      };

      const operatorNameForAdd = typeof window !== 'undefined'
        ? (localStorage.getItem("wardenUsername") || localStorage.getItem("userName") || localStorage.getItem("userType") || "Admin")
        : "Admin";

      const res = await fetch("/api/students", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-email": operatorNameForAdd,
        },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      if (res.ok && data.success) {
        showToast(`Student "${addStudentForm.name || 'new profile'}" manually registered successfully!`, "success");
        setAddStudentForm({});
        setCurrentTab("permissions");
      } else {
        showToast(data.error || "Failed to register student", "error");
      }
    } catch (err: any) {
      showToast("Network error: " + err.message, "error");
    } finally {
      setIsSavingStudent(false);
    }
  };

